// `auto` contrast over $primary, as in widget/optionlist). ListView has no border,
// so a focused list's whole interior gets Textual's `background-tint: $foreground
// 5%` ($surface-focused-tint) — the focus cue that, with the block-cursor swap,
// distinguishes focused from blurred. (Blurred-highlight / hover colours match
// widget/radio.)
func (m Model) rowColors(i int) (fg, bg gocolor.Color, bold bool) {
	switch {
	case i == m.index && m.focused:
		return style.Active().Color(style.BlockCursorForeground), style.Active().Color(style.Primary), true
	case i == m.index:
		return style.Active().Color(style.Text), style.Active().Color(style.BlockCursorBlurredBackground), false
	case i == m.hovered:
		return style.Active().Color(style.Text), style.Active().Color(style.BlockHoverBackground), false
	case m.focused:
		return style.Active().Color(style.Text), style.Active().Color(style.SurfaceFocusedTint), false
	default:
		return style.Active().Color(style.Text), style.Active().Color(style.Surface), false
	}
}

// Render returns the borderless row column on $surface (Textual ListView has no
// border of its own — the host app supplies any frame). Each row is padded to the
// content width so the highlight/hover fill spans the row. Every row is exactly ONE
// physical line — rowAt, the scrollbar and the host's zones rely on it — so a row
// narrower than its text clips it (as Textual crops a Label wider than its
// ListItem); it never wraps.
func (m Model) Render() string {
	if !m.scrolls() {
		w := m.rowWidth()
		rows := make([]string, len(m.items))
		for i := range m.items {
			rows[i] = m.renderRow(i, w)
		}
		return lipgloss.JoinVertical(lipgloss.Left, rows...)
	}

	// Overflowing: render the visible window (narrowed by the scrollbar gutter) and
	// join the right-edge scrollbar, keeping the widget's outer width constant.
	w := m.contentWidth()
	rows := make([]string, m.height)
	for r := 0; r < m.height; r++ {
		rows[r] = m.renderRow(m.offset+r, w)
	}
	body := lipgloss.JoinVertical(lipgloss.Left, rows...)
	bar := scrollbar.RenderVertical(m.height, len(m.items), m.offset,
		m.thumbColor(), style.Active().Color(style.ScrollbarBackground))
	return lipgloss.JoinHorizontal(lipgloss.Top, body, bar)
}

// renderRow draws row i at width w: the Label in the row colours, then the
// optional dim Suffix (fg blended toward the row bg, as Textual renders `dim`),
// padded on the row background so the highlight/hover fill spans the row.
//
// Lip Gloss's Width word-wraps BEFORE MaxWidth truncates, so the row text is
// clipped to w first and Width only pads. The clip is of the WHOLE line
// ([rowtext.Clip] of Label+Suffix), split back into its two styled pieces at the
// Label boundary: clipping the pieces separately would let the Suffix fill a cell
// freed by a dropped wide character ("A日"+"X" at 2 cells → "AX"), where Textual
// crops the line to "A ". A zero-cell row renders nothing: Lip Gloss reads
// Width(0)/MaxWidth(0) as unrestricted, which would overflow the label past the
// geometry rowAt hit-tests against.
func (m Model) renderRow(i, w int) string {
	if w <= 0 {
		return ""
	}
	fg, bg, bold := m.rowColors(i)
	if len(m.items[i].Segments) > 0 {
		return m.renderSegmentsRow(i, w, fg, bg, bold)
	}
	label, suffix := m.rowParts(i)
	kept := rowtext.Clip(label+suffix, w)
	if len(kept) <= len(label) {
		label, suffix = kept, ""
	} else {
		suffix = kept[len(label):]
	}
	if suffix == "" && m.items[i].Suffix == "" {
		return lipgloss.NewStyle().Foreground(fg).Background(bg).Bold(bold).
			Width(w).MaxWidth(w).Render(label)
	}
	labelS := lipgloss.NewStyle().Foreground(fg).Background(bg).Bold(bold).Render(label)
	if suffix != "" {
		labelS += lipgloss.NewStyle().Foreground(style.DimColor(bg, fg)).Background(bg).
			Bold(bold).Render(suffix)
	}
	return lipgloss.NewStyle().Background(bg).Width(w).MaxWidth(w).Render(labelS)
}

// View implements tea.Model (Bubble Tea v2). MouseModeAllMotion is requested so
// the host receives clicks AND bare hover motion (the row tint).
func (m Model) View() tea.View {
	v := tea.NewView(m.Render())
	v.MouseMode = tea.MouseModeAllMotion
	return v
}

// renderSegmentsRow draws a [Item.Segments] row at width w over the row colours: the
// joined one-line text is clipped ONCE (rowtext.Clip, a byte prefix) and split back
// at the segment boundaries, so a wide character dropped at the edge never lets a
// later segment slide into its cell (memory clip-combined-row); each piece takes its
// own fg (nil = the row fg; Dim blends toward the row bg) with bold OR'd, and the row
// is padded on its background so the highlight/hover fill spans it.
func (m Model) renderSegmentsRow(i, w int, fg, bg gocolor.Color, bold bool) string {
	segs := m.segmentsOneLine(i)
	keep := len(rowtext.Clip(segmentsText(segs), w))
	var b strings.Builder
	for _, sg := range segs {
		if keep <= 0 {
			break
		}
		text := sg.Text
		if len(text) > keep {
			text = text[:keep]
		}
		keep -= len(text)
		f := fg
		if sg.Fg != nil {
			f = sg.Fg
		}
		if sg.Dim {
			f = style.DimColor(bg, f)
		}
		b.WriteString(lipgloss.NewStyle().Foreground(f).Background(bg).Bold(bold || sg.Bold).Render(text))
	}
	return lipgloss.NewStyle().Background(bg).Width(w).MaxWidth(w).Render(b.String())
}
